export interface RetryPolicy {
  maxAttempts: number;      // total delivery attempts including first
  baseDelayMs: number;
  maxDelayMs: number;
  jitterRatio: number;      // 0..1
}

export const DEFAULT_RETRY_POLICY: RetryPolicy = {
  maxAttempts: 4,
  baseDelayMs: 500,
  maxDelayMs: 30_000,
  jitterRatio: 0.2,
};

export function shouldRetry(policy, attempt, statusCode, error): boolean { ... }
export function nextDelayMs(policy, attempt, random = Math.random): number { ... }
