import {
  DEFAULT_RETRY_POLICY,
  nextDelayMs,
  type RetryPolicy,
} from "./retry-policy";

export interface DeliveryJob {
  id: string;
  tenantId: string;
  url: string;
  body: unknown;
  /** Delivery attempts completed before this job was claimed. */
  attempts: number;
  nextAttemptAt: string;
}

export interface ClaimOptions {
  workerId: string;
  now: Date;
  leaseMs: number;
}

export interface DeliveryStore {
  claimNext(options: ClaimOptions): Promise<DeliveryJob | null>;
  renewLease(jobId: string, workerId: string, leaseMs: number): Promise<boolean>;
  markDelivered(jobId: string, workerId: string, statusCode: number): Promise<void>;
  markDead(jobId: string, workerId: string, reason: string): Promise<void>;
  scheduleRetry(
    jobId: string,
    workerId: string,
    nextAttemptAt: Date,
    reason: string,
  ): Promise<void>;
}

export interface HttpClient {
  post(
    url: string,
    body: unknown,
    headers: Record<string, string>,
    timeoutMs: number,
  ): Promise<{ status: number }>;
}

export const DELIVERY_LIMITS = {
  /** A claimed job is invisible to other workers for this long. */
  leaseMs: 5_000,
  /** Hard deadline for a single outbound HTTP request. */
  httpTimeoutMs: 15_000,
} as const;

export interface DeliveryOptions {
  workerId: string;
  policy?: RetryPolicy;
  leaseMs?: number;
  httpTimeoutMs?: number;
}

export type PulseResult =
  | "idle"
  | "delivered"
  | "retry_scheduled"
  | "dead_lettered";

export class WebhookDelivery {
  private readonly policy: RetryPolicy;
  private readonly leaseMs: number;
  private readonly httpTimeoutMs: number;

  constructor(
    private readonly store: DeliveryStore,
    private readonly http: HttpClient,
    private readonly clock: { now(): Date },
    private readonly options: DeliveryOptions,
  ) {
    this.policy = options.policy ?? DEFAULT_RETRY_POLICY;
    this.leaseMs = options.leaseMs ?? DELIVERY_LIMITS.leaseMs;
    this.httpTimeoutMs = options.httpTimeoutMs ?? DELIVERY_LIMITS.httpTimeoutMs;
  }

  async pulse(): Promise<PulseResult> {
    const job = await this.store.claimNext({
      workerId: this.options.workerId,
      now: this.clock.now(),
      leaseMs: this.leaseMs,
    });
    if (!job) return "idle";

    const renewed = await this.store.renewLease(
      job.id,
      this.options.workerId,
      this.leaseMs,
    );
    if (!renewed) return "idle";

    let outcome: { status: number } | null = null;
    try {
      outcome = await this.http.post(
        job.url,
        job.body,
        {
          "content-type": "application/json",
          "x-delivery-id": job.id,
          "idempotency-key": `${job.id}:${job.attempts + 1}`,
        },
        this.httpTimeoutMs,
      );
    } catch {
      outcome = null;
    }

    if (outcome && outcome.status >= 200 && outcome.status < 300) {
      await this.store.markDelivered(
        job.id,
        this.options.workerId,
        outcome.status,
      );
      return "delivered";
    }

    const attemptsMade = job.attempts + 1;
    const reason = outcome ? `HTTP ${outcome.status}` : "request failed";

    if (attemptsMade > this.policy.maxAttempts) {
      await this.store.markDead(job.id, this.options.workerId, reason);
      return "dead_lettered";
    }

    const delayMs = nextDelayMs(this.policy, attemptsMade);
    const nextAttemptAt = new Date(this.clock.now().getTime() + delayMs);
    await this.store.scheduleRetry(
      job.id,
      this.options.workerId,
      nextAttemptAt,
      reason,
    );
    return "retry_scheduled";
  }
}

export interface RetryPolicy {
  /** Total delivery attempts allowed, including the first. */
  maxAttempts: number;
  /** Delay before the first retry, before jitter. */
  baseDelayMs: number;
  /** Hard ceiling for any single retry delay. */
  maxDelayMs: number;
  /** Fractional jitter around the computed delay, in the range 0..1. */
  jitterRatio: number;
}

export interface DeliveryOutcome {
  status: number;
}

export const DEFAULT_RETRY_POLICY: RetryPolicy = {
  maxAttempts: 5,
  baseDelayMs: 1_000,
  maxDelayMs: 60_000,
  jitterRatio: 0.25,
};

/**
 * Transport failures and retryable HTTP statuses should be retried.
 * Other 4xx responses are deterministic and must be dead-lettered at once.
 */
export function isRetryable(outcome: DeliveryOutcome | null): boolean {
  if (!outcome) return true;
  if (outcome.status === 408 || outcome.status === 429) return true;
  if (outcome.status >= 400 && outcome.status < 500) return false;
  return outcome.status >= 500;
}

/**
 * `attempt` is the one-based number of the attempt that just failed.
 */
export function nextDelayMs(
  policy: RetryPolicy,
  attempt: number,
  random: () => number = Math.random,
): number {
  const exponential = policy.baseDelayMs * 2 ** attempt;
  const capped = Math.min(exponential, policy.maxDelayMs);
  const jitter = capped * policy.jitterRatio * (random() * 2 - 1);
  return Math.round(capped + jitter);
}

